-- Run this in the Supabase SQL Editor before opening QuestLog.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default 'Personal QuestLog', total_xp integer not null default 0 check(total_xp>=0), gold integer not null default 0 check(gold>=0), completed_tasks integer not null default 0 check(completed_tasks>=0), last_draw_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, category text not null check(category in ('daily','weekly','monthly')), notes text not null default '', priority text not null default 'normal' check(priority in ('normal','high')), status text not null default 'pending' check(status in ('pending','in-progress','completed')), conditions jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.activity_logs (id bigint generated always as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, message text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.level_history (id bigint generated always as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, level integer not null, total_xp integer not null, created_at timestamptz not null default now());
create table if not exists public.unlocked_skills (user_id uuid not null references public.profiles(id) on delete cascade, skill_id text not null, unlocked_at timestamptz not null default now(), primary key(user_id,skill_id));
create table if not exists public.monster_battles (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, monster_name text not null, outcome text not null check(outcome in ('won','lost')), reward_xp integer not null default 0, reward_gold integer not null default 0, task_id uuid references public.tasks(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.event_records (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, event_name text not null, selected_option text, reward_xp integer not null default 0, reward_gold integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.daily_spins (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, spin_date date not null, reward_type text not null, reward_xp integer not null default 0, reward_gold integer not null default 0, created_at timestamptz not null default now(), unique(user_id,spin_date));
alter table public.profiles enable row level security; alter table public.tasks enable row level security; alter table public.activity_logs enable row level security; alter table public.level_history enable row level security; alter table public.unlocked_skills enable row level security; alter table public.monster_battles enable row level security; alter table public.event_records enable row level security; alter table public.daily_spins enable row level security;
create policy "own profiles" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "own tasks" on public.tasks for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own activity" on public.activity_logs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own levels" on public.level_history for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own skills" on public.unlocked_skills for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own battles" on public.monster_battles for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own events" on public.event_records for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own spins" on public.daily_spins for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create index if not exists tasks_user_created_idx on public.tasks(user_id,created_at desc);
create index if not exists activity_user_created_idx on public.activity_logs(user_id,created_at desc);
